/**
 * Builds a field graph: generic math and geometry nodes evaluated by the native core. Shared nodes
 * are computed once per sample point and \`select\` evaluates only the branch it takes.
 *
 * \`\`\`ts
 * const f = new FieldGraph();
 * const bank = f.sub(f.abs(f.sub(f.x, f.sines(f.x, f.z, 10, [[0, 0.035, 0, 11]]))), 5);
 * f.output('bank', bank);
 * \`\`\`
 */
export declare class FieldGraph {
    constant(value: number): FieldRef;
    /** A named input: \`x\`/\`z\` (local frame) for terrain fields; u, v, row, col, i, count, r0… elsewhere. */
    input(name: string): FieldRef;
    get x(): FieldRef;
    get z(): FieldRef;
    add(a: FieldInput, b: FieldInput): FieldRef;
    sub(a: FieldInput, b: FieldInput): FieldRef;
    mul(a: FieldInput, b: FieldInput): FieldRef;
    div(a: FieldInput, b: FieldInput): FieldRef;
    /** a + b + c… left to right. */
    sum(...values: FieldInput[]): FieldRef;
    /** a · b · c… left to right. */
    product(...values: FieldInput[]): FieldRef;
    min(...args: FieldInput[]): FieldRef;
    max(...args: FieldInput[]): FieldRef;
    neg(a: FieldInput): FieldRef;
    abs(a: FieldInput): FieldRef;
    sqrt(a: FieldInput): FieldRef;
    floor(a: FieldInput): FieldRef;
    square(a: FieldInput): FieldRef;
    sin(a: FieldInput): FieldRef;
    cos(a: FieldInput): FieldRef;
    exp(a: FieldInput): FieldRef;
    /** \`a\` to the power \`b\`. */
    pow(a: FieldInput, b: FieldInput): FieldRef;
    /** \`a − floor(a)\`. */
    fract(a: FieldInput): FieldRef;
    /**
     * Value noise in 0..1 on a unit lattice: the common sine-hash shader noise, smoothstep-blended.
     * With \`period\`, it repeats every \`period\` cells in x (to wrap around a lathe without a seam).
     */
    noise(x: FieldInput, z: FieldInput, period?: number): FieldRef;
    /** a + (b − a) · t, componentwise on numbers or fields. */
    mix(a: FieldInput, b: FieldInput, t: FieldInput): FieldRef;
    hypot(...args: FieldInput[]): FieldRef;
    /** Hermite smoothstep of \`a\` clamped to 0..1. */
    smooth(a: FieldInput): FieldRef;
    clamp(a: FieldInput, lo: FieldInput, hi: FieldInput): FieldRef;
    /** \`le\` where \`test\` <= 0, otherwise \`gt\` (only the chosen branch is evaluated). */
    select(test: FieldInput, le: FieldInput, gt: FieldInput): FieldRef;
    /** base + Σ amp · sin(fx·x + fz·z + phase), terms as [fx, fz, phase, amp]. */
    sines(x: FieldInput, z: FieldInput, base: number, terms: readonly (readonly [
        number,
        number,
        number,
        number
    ])[]): FieldRef;
    /** Σ height · max(0, 1 − u² − v²)^power over oriented ellipses [x, z, height, radiusU, radiusV, yaw]. */
    bumps(x: FieldInput, z: FieldInput, items: readonly (readonly [
        number,
        number,
        number,
        number,
        number,
        number
    ])[], power?: number): FieldRef;
    /** The smallest signed distance to the shapes (minus each one's offset); +∞ with none. */
    distance(x: FieldInput, z: FieldInput, shapes: readonly FieldShape[]): FieldRef;
    /** Π smoothstep((distance − offset) / width): 0 at the shapes, 1 beyond their fade. */
    falloff(x: FieldInput, z: FieldInput, shapes: readonly FieldShape[]): FieldRef;
    /** The largest depth inside any of the boxes (min of side clearances, minus offset); −∞ with none. */
    depth(x: FieldInput, z: FieldInput, shapes: readonly FieldShape[]): FieldRef;
    /** Names a field so recipes can refer to it. Returns the name. */
    output(name: string, value: FieldInput): string;
    toJSON(): {
        nodes: Node[];
        outputs: Record<string, number>;
    };
}

